variants.code_sketch:
xs := []int{0, 1, 2, 3, 4, 5}
xs = slices.DeleteFunc(xs, func(v int) bool { return v%2 == 0 })
// xs == []int{1, 3, 5}: one compaction pass, tail cleared for the GC

n := 0
for _, v := range xs {
    if keep(v) {
        xs[n] = v
        n++
    }
}
clear(xs[n:])   // release references held by the removed slots
xs = xs[:n]
